# Define the worst-case configuration P for a small representative set (3 pairs positive, 3 pairs negative)
P_pos = [{'x1', 'x1'}, {'x2', 'x2'}, {'x3', 'x3'}]
P_neg = [{-'m1', -'m1'}, {-'m2', -'m2'}, {-'m3', -'m3'}]
P_total = P_pos + P_neg

# Case 1: E consists of only positive numbers
# E = {1, 2, 3} (representing the required positive elements)
E_pos = {1, 2, 3}
score_pos = 0
for p in P_total:
    if any(x in E_pos for x in p):
        score_pos += 1
print(f"Score with E_pos: {score_pos}")

# Case 2: E consists of only negative numbers
# E = {-35, -36, -37} (representing the required negative elements)
E_neg = {-35, -36, -37}
score_neg = 0
for p in P_total:
    if any(x in E_neg for x in p):
        score_neg += 1
print(f"Score with E_neg: {score_neg}")
